  const LLR_B64 = "";
  const MT = 1735689600000;
  window.__TAURI_INTERNALS__ = {
    invoke: async (cmd, args) => {
      switch (cmd) {
        case 'scan_dir':
          return JSON.parse(JSON.stringify(TREE));
        case 'parse_file':
          return PARSES[args.path] || { type: 'error', message: '文件不存在: ' + args.path };
        case 'file_mtime':
          return MT;
        case 'read_file': {
          const bin = atob(LLR_B64);
          return Uint8Array.from(bin, (c) => c.charCodeAt(0));
        }
        case 'save_file':
          return null;
        case 'plugin:dialog|open':
          return args && args.options && args.options.directory
            ? DEMO_DIR
            : DEMO_DIR + '\\Demo_LLR_Requirements.xlsx';
        case 'plugin:dialog|save':
          return DEMO_DIR + '\\代码文档_演示.xlsx';
        default:
          return null;
      }
    },
  };
